      </div>
      <div class="gender-stats">
        <div class="gender-stat">Primary: <strong>Nearly closed</strong></div>
        <div class="gender-stat">Secondary: <strong>Nearly closed</strong></div>
        <div class="gender-stat">Tertiary: <strong>Women exceed men</strong></div>
      </div>
    </div>

  </div>

</body>
